import {seasonState,seasonProgress,passXP} from './season.js';
export const DAILY_QUESTS=[{id:'food',name:'100 yem topla',target:100,gold:4000,xp:50},{id:'goldSpent',name:'5.000 Gold kullan',target:5000,gold:3000,xp:50},{id:'kills',name:'3 rakip yen',target:3,gold:6000,xp:75},{id:'seconds',name:'10 dakika oyna',target:600,gold:5000,xp:75}];
export function dayKey(now=Date.now()){return new Date(now+3*3600000).toISOString().slice(0,10)}
export function daily(p,now=Date.now()){if(p.daily?.day!==dayKey(now))p.daily={day:dayKey(now),food:0,goldSpent:0,kills:0,seconds:0,claimed:[]};return p.daily}
export function addXP(p,n,now=Date.now()){p.xp=(p.xp||0)+n*(p.premiumUntil>now?1.25:1)}
export function progress(p,delta,now=Date.now()){seasonProgress(p,delta,now);p.stats??={games:0,food:0,kills:0,goldSpent:0,seconds:0};const d=daily(p,now),before=Math.floor(p.stats.seconds/20);for(const k of ['food','kills','goldSpent','seconds','games']){const n=Math.max(0,Number(delta[k])||0);p.stats[k]=(p.stats[k]||0)+n;if(k in d)d[k]+=n}addXP(p,(delta.kills||0)*10+Math.max(0,Math.floor(p.stats.seconds/20)-before),now)}
export function claimDaily(p,id,now=Date.now()){const q=DAILY_QUESTS.find(q=>q.id===id),d=daily(p,now);if(!q||d[id]<q.target||d.claimed.includes(id))throw Error('Görev tamamlanmadı veya ödül zaten toplandı.');seasonState(p,now);d.claimed.push(id);p.gold+=q.gold;passXP(p,q.xp,now);addXP(p,q.xp,now)}
export function dailyLogin(p,now=Date.now()){const key=dayKey(now);if(p.loginDay===key)throw Error('Bugünün giriş ödülü zaten toplandı.');p.loginDay=key;p.bonus+=p.premiumUntil>now?10000:5000}
